// Or narrows to the rows any of alternatives matches, each holding conditions alone.
func (s Product) Or(alternatives ...Product) Product {
	qs := make([]impl.Of[model.Product], len(alternatives))
	for i, a := range alternatives {
		qs[i] = kRuntime(a.q)
	}
	return Product{kScope(kRuntime(s.q).Or(qs...))}
}

// Not narrows to the rows other, holding conditions alone, does not match.
func (s Product) Not(other Product) Product {
	return Product{kScope(kRuntime(s.q).Not(kRuntime(other.q)))}
}

// values holds the value of each column of row, for After, Before, and Cursor. One that may be NULL
// holds MayBeNull, since no page continues by it.
func (Product) values(row model.Product) map[string]any {
	return map[string]any{
		`sku`:      row.SKU,
		`name`:     row.Name,
		`price`:    row.Price,
		`currency`: row.Currency,
	}
}

// After narrows to the rows after row in the scope's order, for the page after the one row is the last of.
func (s Product) After(row model.Product) Product {
	return Product{kScope(kRuntime(s.q).After([]string{`sku`}, s.values(row)))}
}

// Before narrows to the rows before row in the scope's order, for the page before the one row is the first of.
func (s Product) Before(row model.Product) Product {
	return Product{kScope(kRuntime(s.q).Before([]string{`sku`}, s.values(row)))}
}

// Cursor encodes the position of row in the scope's order, for a client to hand back to AfterCursor.
func (s Product) Cursor(row model.Product) (string, error) {
	return kRuntime(s.q).Cursor([]string{`sku`}, s.values(row))
}

// AfterCursor is After the row cursor holds, as Cursor made it in the same order. An empty cursor is the start.
func (s Product) AfterCursor(cursor string) (Product, error) {
	if cursor == "" {
		return s, nil
	}
	var row model.Product
	if err := kRuntime(s.q).DecodeCursor(cursor, []string{`sku`}, map[string]any{
		`sku`:      &row.SKU,
		`name`:     &row.Name,
		`price`:    &row.Price,
		`currency`: &row.Currency,
	}); err != nil {
		return Product{}, err
	}
	return s.After(row), nil
}

// Order is the scope of orders, whose rows are read into model.Order, as //kanna:scopes implies it.
type Order struct{ q scope.Of[model.Order] }

// Orders returns a scope over all the rows of orders.
func Orders() Order { return Order{} }

// Of returns the scope as a repository reads it.
func (s Order) Of() scope.Of[model.Order] { return s.q }

// OrderChangeSet holds explicitly assigned columns of orders.
